import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv, vec3 } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'footer-colophon';

  const W = 6.8, H = 2.0;

  // Background band with vertical gradient
  const bandGeo = new THREE.PlaneGeometry(W, H);
  const bandMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2 });
  const topColor = color('#121218');
  const botColor = color('#0b0b10');
  bandMat.colorNode = mix(topColor, botColor, uv().y.oneMinus());
  const band = new THREE.Mesh(bandGeo, bandMat);
  band.position.set(0, 0, 0);
  group.add(band);

  const disposables = [bandGeo, bandMat];

  function hairline(y, opacityHex = '#23232b') {
    const geo = new THREE.PlaneGeometry(W, 0.006);
    const mat = new MeshBasicNodeMaterial({ color: new THREE.Color(opacityHex) });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, y, 0.001);
    group.add(mesh);
    disposables.push(geo, mat);
    return mesh;
  }

  // top hairline
  hairline(H / 2);
  // second hairline above legal line
  const legalY = -H / 2 + 0.375;
  hairline(legalY + 0.25);

  const textNodes = [];
  function addText(str, style, x, y, z = 0.002, colorHex = '#e8ecf2') {
    if (!str || !ctx.fontAtlas) return null;
    const node = ctx.fontAtlas.createText(str, {
      family: style.family,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: colorHex,
    });
    node.position.set(x, y, z);
    group.add(node);
    textNodes.push(node);
    return node;
  }

  const typo = config.typography || {};
  const leftX = -W / 2 + 0.05;

  // Wordmark block, left 2.0 units
  addText('NOVA ATELIER', typo.wordmark || { family: 'Lora', fontSize: 34, fontWeight: 600, letterSpacing: 0.02, lineHeight: 1 }, leftX, H / 2 - 0.5, 0.002, '#e8ecf2');

  // accent bar beneath wordmark
  const accentGeo = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshBasicNodeMaterial({ color: new THREE.Color('#ff2a38') });
  const accentBar = new THREE.Mesh(accentGeo, accentMat);
  accentBar.position.set(leftX + 0.15, H / 2 - 0.75, 0.002);
  group.add(accentBar);
  disposables.push(accentGeo, accentMat);

  // Link columns
  const columns = [
    { header: 'ATELIER', links: ['Features', 'Collection', 'Pricing'] },
    { header: 'COMPANY', links: ['Journal', 'Visit the Atelier', 'Contact'] },
    { header: 'LEGAL', links: ['Privacy', 'Terms', 'Warranty'] },
  ];

  const colStartX = -W / 2 + 2.0 + 0.375;
  const colW = 1.2;
  const gutter = 0.375;
  const colHeaderStyle = typo['column-header'] || { family: 'JetBrains Mono', fontSize: 9, fontWeight: 700, letterSpacing: 0.12, lineHeight: 1.2 };
  const linkStyle = typo.link || { family: 'JetBrains Mono', fontSize: 13, fontWeight: 400, letterSpacing: 0, lineHeight: 1.8 };

  const linkMeshes = [];

  columns.forEach((col, i) => {
    const x = colStartX + i * (colW + gutter);
    const headerY = H / 2 - 0.4;
    addText(col.header, colHeaderStyle, x, headerY, 0.002, '#8a8a94');

    let ly = headerY - 0.28;
    col.links.forEach((linkText) => {
      const linkNode = addText(linkText, linkStyle, x, ly, 0.002, '#e8ecf2');
      if (linkNode) linkMeshes.push({ node: linkNode, base: '#e8ecf2', hover: '#ff2a38' });
      ly -= 0.13 * 1.8;
    });
  });

  // Legal line
  const legalStyle = typo.legal || { family: 'JetBrains Mono', fontSize: 9, fontWeight: 400, letterSpacing: 0.04, lineHeight: 1.4 };
  addText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    legalStyle,
    leftX,
    -H / 2 + 0.15,
    0.002,
    '#8a8a94'
  );

  group.position.set(
    config.scenePosition?.[0] ?? 0,
    config.scenePosition?.[1] ?? 0,
    config.scenePosition?.[2] ?? 0
  );

  // Mount animation: fade-up of whole band
  group.visible = true;
  const initialY = group.position.y;
  group.traverse((obj) => {
    if (obj.material) {
      obj.material.transparent = true;
      if (obj.material.opacity === undefined) obj.material.opacity = 1;
      obj.material.opacity = 0;
    }
  });
  group.position.y = initialY + 0.2;

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: initialY,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  group.traverse((obj) => {
    if (obj.material) {
      tl.to(obj.material, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
    }
  });

  // Hover handlers for links (magnetic-cursor style color/z transitions)
  const handlers = {
    onPointerMove: (evt) => {
      // no-op placeholder for raycast-driven hover; consumer supplies intersect info
    },
    onLinkHover: (linkNode) => {
      const entry = linkMeshes.find((l) => l.node === linkNode);
      if (!entry) return;
      gsap.to(entry.node.position, { z: 0.02, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
      if (entry.node.material && entry.node.material.color) {
        gsap.to(entry.node.material.color, {
          r: new THREE.Color(entry.hover).r,
          g: new THREE.Color(entry.hover).g,
          b: new THREE.Color(entry.hover).b,
          duration: 0.14,
        });
      }
    },
    onLinkUnhover: (linkNode) => {
      const entry = linkMeshes.find((l) => l.node === linkNode);
      if (!entry) return;
      gsap.to(entry.node.position, { z: 0, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
      if (entry.node.material && entry.node.material.color) {
        gsap.to(entry.node.material.color, {
          r: new THREE.Color(entry.base).r,
          g: new THREE.Color(entry.base).g,
          b: new THREE.Color(entry.base).b,
          duration: 0.14,
        });
      }
    },
  };

  group.userData.handlers = handlers;
  group.userData.linkMeshes = linkMeshes.map((l) => l.node);

  group.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((d) => d.dispose && d.dispose());
    textNodes.forEach((t) => {
      if (t.userData && t.userData.cleanup) t.userData.cleanup();
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
  };

  return group;
}
